@import 'c/ihStyles';

:host {
    display: block;
    padding-bottom: 0.75rem;
}
.events {
    margin-top: 0.75rem;
}
.check {
    display: inline-block;
    margin-top: 8px;
}
.result {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-top: 12px;
    padding: 8px 12px;
    border-radius: 8px;
    overflow-wrap: anywhere;
}
.result_ok {
    background: var(--ih-ok-bg);
    color: var(--ih-ok-ink);
}
.result_bad {
    background: var(--ih-bad-bg);
    color: var(--ih-bad-ink);
}
.list {
    list-style: none;
    margin: 0;
    padding: 0;
    max-height: 30rem;
    overflow-y: auto;
}
.item {
    padding: 10px 16px;
    border-top: 1px solid var(--ih-line-2);
}
.line1 {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}
